// game_registry.hpp — the five Action Max games, their Singe-authored
// parameters, and SD media resolution + integrity status.
//
// game.cfg files (generated by tools/prepare_media.ps1 from the original
// Singe .txt scripts) are the single source of truth; the defaults below are
// the verified script values and only apply when a .cfg is missing.
#pragma once

#include <string>
#include <vector>
#include <cstdint>

struct GameConfig {
    std::string id;      // folder id, e.g. "bluethunder"
    std::string title;   // display name
    std::string media;   // media filename relative to media/<id>/

    // Singe-authored playback/geometry parameters (overlay 360x240 space).
    int highThreshold   = 127;
    int lowThreshold    = 20;
    int sensorX         = 312;   // playfield extent
    int sensorY         = 205;
    int sensorLeft      = 282;   // suction-cup sensor box top-left
    int sensorTop       = 182;
    int lengthIntro     = 354;   // authored tape frame counts (29.97 numbering)
    int lengthGame      = 0;
    int lengthMenu      = 96;
    int backgroundFrame = 0;     // still frame shown behind the title screen

    // Resolved at boot by the registry.
    std::string mediaPath;      // absolute path on device, empty if missing
    uint64_t    mediaSize  = 0;
    std::string mediaQuickHash; // quick integrity digest, empty if unchecked
    bool        ready      = false;   // present and passed integrity check
    std::string statusNote;    // human-readable reason when not ready
};

class GameRegistry {
public:
    // Loads game.cfg files, resolves media paths and verifies integrity
    // against the bundled manifest.  Returns the number of ready games.
    //   quick: compare size + SHA-256 of first 256 KiB + size trailer
    //   full : SHA-256 of the entire file (slow, opt-in)
    int load(bool fullVerify);

    const std::vector<GameConfig>& games() const { return games_; }
    int readyCount() const;

    // Common media (intro / menu), resolved like game media.
    std::string introMediaPath;
    std::string menuMediaPath;
    bool        commonReady = false;
    std::string commonStatusNote;

private:
    bool parseGameCfg(const std::string& path, GameConfig& cfg);
    void resolveMedia(GameConfig& cfg, bool fullVerify);

    std::vector<GameConfig> games_;
    // manifest entry: relpath -> (full sha256, quick sha256, size)
    struct ManifestEntry { std::string fullHash; std::string quickHash; uint64_t size; };
    std::vector<std::pair<std::string, ManifestEntry>> manifest_;
    bool manifestLoaded_ = false;
    bool fullVerify_ = false;
};
